export function makeLocalLlmContent(shared: Pick<AcademyUnitContent, 'anatomyOrder' | 'boundary' | 'preparation'>): AcademyUnitContent[] {
  if (lessons.length !== localLlmLessons.length) throw new Error('Every local LLM lesson needs authored teaching content.')
  return localLlmLessons.map(([unitId, , , , title, outcome], index) => {
    const lesson = lessons[index]
    const [prompt, correct, correctFeedback, incorrect, incorrectFeedback] = lesson.check
    return {
      ...shared, unitId, anatomyKind: 'concept', access: 'open', location: title, goal: outcome,
      purpose: lesson.explanation[0],
      scope: { estimatedTime: '10 to 15 minutes', requiredActions: lesson.steps.length + 1, activityType: 'reading-and-check', environment: 'browser-only prepared evidence', changes: 'No files, accounts, devices, networks, or services change.' },
      words: lesson.terms.map(([term, definition, example]) => ({ term, definition, example })),
      example: { input: lesson.example, question: lesson.question }, prediction: 'Choose an answer before reading the prepared result.', preparedResult: lesson.result,
      explanationSteps: lesson.explanation,
      practice: { id: `${unitId}-practice`, title: 'Try it', prompt: outcome, preparedEvidence: lesson.evidence, steps: lesson.steps, expectedResult: lesson.expected, acceptableVariation: 'Your wording can differ; explain your choice using the evidence.', recovery: lesson.recovery },
      knowledgeCheck: { prompt, choices: index % 2 === 0
        ? [{ id: 'a', label: correct, correct: true, feedback: correctFeedback }, { id: 'b', label: incorrect, correct: false, feedback: incorrectFeedback }]
        : [{ id: 'a', label: incorrect, correct: false, feedback: incorrectFeedback }, { id: 'b', label: correct, correct: true, feedback: correctFeedback }], retry: lesson.recovery },
      recap: [lesson.result, lesson.expected], notClaimed: lesson.limits,
      stopResume: { savedFact: `Bookmark this lesson: ${title}. Completed knowledge checks are saved; unsent answers are not.`, returnQuestion: lesson.question, nextChoice: 'Continue to the next named lesson, or choose another course from the path.' }, sourceIds: lesson.sources,
    }
  })
}
